def _save_upload(uploaded_file, folder: Path) -> Path:
    folder.mkdir(parents=True, exist_ok=True)
    destination = folder / Path(uploaded_file.name).name
    destination.write_bytes(uploaded_file.getvalue())
    return destination


def _read_status(path_value: str | None) -> dict:
    if not path_value:
        return {}
    path = Path(path_value)
    try:
        return json.loads(path.read_text(encoding="utf-8")) if path.is_file() else {}
    except Exception:
        return {}


def _stop_queue() -> None:
    status_path_value = st.session_state.get("status_path")
    if status_path_value:
        path = Path(status_path_value)
        try:
            status = json.loads(path.read_text(encoding="utf-8")) if path.exists() else {}
            status["stop_requested"] = True
            path.write_text(json.dumps(status, indent=2), encoding="utf-8")
        except Exception:
            pass
    proc = st.session_state.get("queue_process")
    if proc is not None and proc.poll() is None:
        st.session_state["run_state"] = "Stop requested"


def _refresh_queue_state() -> dict:
    status = _read_status(st.session_state.get("status_path"))
    proc = st.session_state.get("queue_process")
    if proc is not None:
        code = proc.poll()
        if code is not None and status.get("state") not in {"Completed", "Completed with failures", "Stopped"}:
            status["state"] = "Exited" if code else "Completed"
            status["exit_code"] = code
        if status.get("state"):
            st.session_state["run_state"] = status["state"]
    return status


@st.cache_data(show_spinner=False)
def _background_css() -> str:
    """Page background from assets/rail_background.jpg (kept sharp; only a light tint for legibility)."""
    import base64
    image_path = APP_DIR / "assets" / "rail_background.jpg"
    fallback = ".stApp {background:radial-gradient(ellipse at top right,#142b42 0%,#0e1117 48%);}"
    if not image_path.is_file():
        return fallback
    data = base64.b64encode(image_path.read_bytes()).decode("ascii")
    return (
        ".stApp {background:linear-gradient(rgba(6,12,20,.18),rgba(6,12,20,.18)),"
        f"url(data:image/jpeg;base64,{data}) center center / cover no-repeat fixed;}}"
        " .stApp > header {background:transparent !important;}"
        " div[data-testid=\"stMainBlockContainer\"], section.main > div.block-container"
        " {background:rgba(8,14,22,.52); border-radius:18px; padding-left:2rem !important;"
        " padding-right:2rem !important; padding-bottom:2rem !important; margin-top:.5rem;}"
        " div[data-testid=\"stMainBlockContainer\"] h2, div[data-testid=\"stMainBlockContainer\"] h3"
        " {color:#fff !important; text-shadow:0 1px 6px #000a;}"
    )


