with st.sidebar:
    st.subheader("Test setup")
    selected_tests = st.multiselect(
        "Select tests (execution follows this order)",
        options=list(TESTS.keys()),
        default=[],
        format_func=lambda key: TESTS[key]["label"],
        key="selected_tests_v2",
    )
    toc_upload = st.file_uploader("Upload TOC workbook", type=["xlsx", "xlsm"], key="toc_upload")
    coords_upload = st.file_uploader("Upload configuration / coordinates workbook", type=["xlsx", "xlsm"], key="coords_upload")
    track_coords_upload = st.file_uploader("Upload track coordinates workbook", type=["xlsx", "xlsm"], key="track_coords_upload", help="Upload the track coordinate workbook used by tests that operate tracks in the simulator.")
    st.divider()
    st.warning("Use only in an isolated C-FAT test panel/simulator. Never connect this automation to live railway signalling equipment.")
    isolated_confirm = st.checkbox("I confirm this is an isolated test/simulator environment.", key="isolated_confirm")

st.subheader("Verified test drivers and workbook requirements")
if not selected_tests:
    st.info("No test selected. Choose one or more tests in the sidebar; no test is loaded or started automatically.")
for key in selected_tests:
    spec = TESTS[key]
    with st.container(border=True):
        st.markdown(f"**{spec['label']}** (`{spec['source']}`)")
        st.caption(f"Driver sequence: {spec['drivers']}")
        st.caption(f"Workbook requirements: {spec['inputs']}")

status_path_value = st.session_state.get("status_path")
status = _refresh_queue_state()
proc = st.session_state.get("queue_process")
busy = proc is not None and proc.poll() is None

col_a, col_b, col_c = st.columns(3)
with col_a:
    st.metric("Selected tests", len(selected_tests))
with col_b:
    st.metric("Run status", status.get("state", st.session_state.get("run_state", "Not started")))
with col_c:
    current_test = status.get("current_test") or "—"
    st.metric("Current test", TESTS.get(current_test, {}).get("label", current_test))

start_col, stop_col, refresh_col = st.columns([1, 1, 1])
with start_col:
    start_clicked = st.button("▶ Run selected tests", type="primary", disabled=busy, use_container_width=True)
with stop_col:
    stop_clicked = st.button("■ Stop queue", disabled=not busy, use_container_width=True)
with refresh_col:
    refresh_clicked = st.button("↻ Refresh status", use_container_width=True)

if start_clicked:
    missing_sources = [TESTS[key]["source"] for key in selected_tests if not (APP_DIR / TESTS[key]["source"]).is_file()]
    if not isolated_confirm:
        st.error("Confirm that this is an isolated test/simulator environment before starting.")
    elif not selected_tests:
        st.error("Select at least one test.")
    elif toc_upload is None or coords_upload is None:
        st.error("Upload both the TOC workbook and the configuration/coordinates workbook.")
    elif not SUITE_FILE.is_file() or not QUEUE_FILE.is_file():
        st.error("Project support files are missing. Restore the EDRC suite and run_queue.py before launching.")
    elif missing_sources:
        st.error("Missing test source file(s): " + ", ".join(missing_sources))
    else:
        try:
            upload_dir = INPUT_ROOT / uuid.uuid4().hex
            toc_path = _save_upload(toc_upload, upload_dir)
            coords_path = _save_upload(coords_upload, upload_dir)
            track_coords_path = _save_upload(track_coords_upload, upload_dir) if track_coords_upload is not None else None
            session_dir = REPORTS_ROOT / datetime.now().strftime("SESSION_%Y%m%d_%H%M%S")
            session_dir.mkdir(parents=True, exist_ok=True)
            status_path = session_dir / "QUEUE_STATUS.json"
            config_path = session_dir / "QUEUE_CONFIG.json"
            config_path.write_text(json.dumps({
                "tests": selected_tests,
                "toc": str(toc_path),
                "coords": str(coords_path),
                "track_coords": str(track_coords_path) if track_coords_path else None,
                "session_dir": str(session_dir),
                "status_path": str(status_path),
            }, indent=2), encoding="utf-8")
            status_path.write_text(json.dumps({
                "state": "Starting", "selected_tests": selected_tests,
                "current_test": None, "completed": 0, "total": len(selected_tests),
                "results": [], "stop_requested": False,
            }, indent=2), encoding="utf-8")
            queue_proc = subprocess.Popen(
                [sys.executable, "-u", str(QUEUE_FILE), str(config_path)],
                cwd=str(APP_DIR),
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL,
                creationflags=(subprocess.CREATE_NEW_PROCESS_GROUP if os.name == "nt" else 0),
            )
            st.session_state["queue_process"] = queue_proc
            st.session_state["status_path"] = str(status_path)
            st.session_state["session_dir"] = str(session_dir)
            st.session_state["run_state"] = "Running"
            st.success("Sequential test queue started. Each test will use its verified driver sequence and a separate report folder.")
            st.rerun()
        except Exception as exc:
            st.session_state["run_state"] = "Launch failed"
            st.error(f"Could not start test queue: {type(exc).__name__}: {exc}")

if stop_clicked:
    _stop_queue()
    st.warning("Stop request sent to the sequential queue.")

if refresh_clicked:
    status = _refresh_queue_state()

status = _refresh_queue_state()
if status:
    completed = int(status.get("completed", 0) or 0)
    total = int(status.get("total", len(status.get("selected_tests", []))) or 0)
    if total:
        st.progress(min(completed / total, 1.0), text=f"Tests completed: {completed}/{total}")
    if status.get("current_test"):
        st.info(f"Running: {TESTS.get(status['current_test'], {}).get('label', status['current_test'])}")
    if status.get("results"):
        st.subheader("Queue results")
        st.dataframe(status["results"], use_container_width=True, hide_index=True)

st.subheader("Live execution log")
log_path_value = status.get("current_log")
if log_path_value and Path(log_path_value).is_file():
    try:
        log_lines = Path(log_path_value).read_text(encoding="utf-8", errors="replace").splitlines()
        st.code("\n".join(log_lines[-100:]) or "Console log is empty.", language="text")
    except Exception as exc:
        st.warning(f"Could not read execution log: {exc}")
else:
    st.info("The log for the active test appears here after it starts. Refresh status to update it.")

session_value = st.session_state.get("session_dir")
if session_value:
    st.subheader("Generated reports")
    session_dir = Path(session_value)
    report_files = sorted(session_dir.glob("**/*.xlsx"), key=lambda path: path.stat().st_mtime, reverse=True)
    report_files = [path for path in report_files if path.name not in {"QUEUE_CONFIG.xlsx", "QUEUE_STATUS.xlsx"}]
    if report_files:
        for report in report_files:
            with st.container(border=True):
                left, right = st.columns([4, 1])
                with left:
                    st.write(f"**{report.name}**")
                    st.caption(f"Folder: {report.parent.name} · Modified: {datetime.fromtimestamp(report.stat().st_mtime).strftime('%Y-%m-%d %H:%M:%S')}")
                with right:
                    st.download_button(
                        "Download", data=report.read_bytes(), file_name=report.name,
                        mime="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
                        key=f"download_{report.relative_to(session_dir).as_posix()}",
                        use_container_width=True,
                    )
    else:
        st.caption("No Excel reports have been collected yet. Refresh after a test finishes.")
    st.caption(f"Session folder: {session_dir}")

st.caption("The frontend only orchestrates existing test scripts. Test operation logic and each script's report layout remain in the original backend sources.")
